import json
def transform(g):
    H=len(g); W=len(g[0])
    rows=[r for r in range(H) if any(x==5 for x in g[r])]
    cols=[c for c in range(W) if any(g[r][c]==5 for r in range(H))]
    r0,r1,c0,c1=min(rows),max(rows),min(cols),max(cols)
    marks=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c] not in (0,5)]
    rm=(r0+r1+1)//2; cm=(c0+c1+1)//2
    def quad(r,c): return (0 if r<rm else 1, 0 if c<cm else 1)  # quadrant of a cell
    # assign each marker to nearest quadrant block
    assign={}
    for r,c,col in marks:
        best=None;bd=1e9
        for i in range(r0+1,r1, max(1,(r1-r0-1)//2 or 1)):
            pass
        # compute quadrant block centers
        tops=[r0+1,r0+1+(r1-r0-1)//2]; lefts=[c0+1,c0+1+(c1-c0-1)//2]
        for qi,(qr) in enumerate(tops):
            for qj,(qc) in enumerate(lefts):
                d=abs(r-qr)+abs(c-qc)
                if d<bd: bd=d; best=(qi,qj)
        assign[best]=col
    opp={(0,0):(1,1),(1,1):(0,0),(0,1):(1,0),(1,0):(0,1)}
    out=[row[:] for row in g]
    for qi in range(2):
        for qj in range(2):
            col = assign.get(opp[(qi,qj)], assign.get((qi,qj)))
            rs = range(r0+1+qi*((r1-r0-1)//2 or 1) if qi==0 else r0+1+((r1-r0-1)//2), r0+1+(qi+1)*((r1-r0-1)//2 or 1) if qi==0 else r1)
            cs = range(c0+1+qj*((c1-c0-1)//2 or 1) if qj==0 else c0+1+((c1-c0-1)//2), c0+1+(qj+1)*((c1-c0-1)//2 or 1) if qj==0 else c1)
            for r in rs:
                for c in cs:
                    out[r][c]=col
    return out
